{"number":334,"title":"DESIGN.md trade-offs: delivery mode is now a security knob; name the vendored mount&#39;s supply-chain improvement","body":"From a design review of `mount/DESIGN.md` (#315). Doc-only.

**The improvement (worth recording as a design benefit):** the vendored mount closes a real supply-chain exposure — consumers previously executed an unauthenticated, unpinned `codeload` tarball at every session start *and on every Bash call* (the PreToolUse guard). Post-flip, consumers execute only code committed in their own history: diffs reviewable, rollback = revert the nightly&#39;s commit.

**The residual (worth a sentence in §10):** for `push`-delivery members, the nightly is an unreviewed fleet-wide code-write channel into `main`; `pr` delivery buys a human review gate on the entire supply chain. That makes `maintenance.delivery` a **security decision**, not just a workflow preference — a member holding secrets or deploy credentials may reasonably choose `pr` for that reason alone. (The preferences fetch remains the one session-time fetch: fail-soft prose, not executed code — acceptable residue, worth naming as such.)","state":"open","html_url":"https://github.com/[REDACTED:env:CCR_TRIGGER_REPO]/issues/334","user":{"login":"missingbulb","id":73882448,"profile_url":"https://github.com/missingbulb","avatar_url":"https://avatars.githubusercontent.com/u/73882448?v=4"},"author_association":"OWNER","labels":["quick-win"],"comments":1,"reactions":{"total_count":0,"+1":0,"-1":0,"laugh":0,"confused":0,"heart":0,"hooray":0,"rocket":0,"eyes":0},"created_at":"2026-07-18T19:49:54Z","updated_at":"2026-07-30T04:45:46Z","has_parent":false,"has_children":false,"closed_by_pull_requests":{"total_count":0,"references":[]}}

[Resource from github at repo://[REDACTED:env:CCR_TRIGGER_REPO]/sha/e86c299d0739d45f29baf488490259a077fec488/contents/packs/static-website/release-workflows.mjs] import { finding } from '../../engine/checks/helpers/findings.mjs';
import { parseConfig } from './stubs/actions/read-site-config/read-config.mjs';

// The static-site release pipeline is VENDORED into each consumer's own
// .github/: the orchestrator (STUB_FILE, named STUB_NAME) owns the triggers and
// calls the two local reusable workflows, which — with the three composite
// actions — the pack materializes alongside it. GitHub resolves a reusable
// workflow or a composite action only from the repo's own .github/, never from
// the shared mount, so "the logic lives in the pack" means the pack holds the
// templates and each repo hosts a managed copy: edit the pack, not the copy.
//
// RELEVANCE FIRST: everything here is gated on the orchestrator existing. A repo
// that declares this pack for the versioning and CI half while its site deploys
// somewhere other than Pages carries no orchestrator, and none of this fires.
export const STUB_FILE = 'static-site-release.yml';
export const STUB_NAME = 'Release static site';
export const CI_STUB_FILE = 'static-site-ci.yml';

// The reusable workflows the pipeline runs on (the orchestrator calls the
// publish one; the publish one calls the deploy one).
export const ORCHESTRATOR_CALL = 'static-site-publish.yml';
export const VENDORED_WORKFLOWS = [ORCHESTRATOR_CALL, 'static-site-deploy-pages.yml'];
// The composite actions those workflows use, at .github/actions/<name>/.
export const VENDORED_ACTIONS = ['read-site-config', 'bump-site-version', 'assemble-site'];

export const stubPath = (file) => `.github/workflows/${file}`;

// Does this repo ship the pipeline? The orchestrator's presence is the marker.
export function shipsPipeline(ctx) {
  const text = ctx.read(stubPath(STUB_FILE));
  if (text === null) return false;
  const name = /^name:\s*['"]?(.+?)['"]?\s*$/m.exec(text)?.[1];
  return name === STUB_NAME;
}

const rule = {
  id: 'sw/release-workflows',
  severity: 'blocking',
  description: 'The static-site orchestrator and the reusable workflows + composite actions it calls must all be vendored into .github/',
  doc: 'packs/static-website/RELEASE.md',
  why: 'the pipeline runs entirely from the repo own .github/ — a missing leg is a release that half-runs: a bumped version with no deploy, or a deploy of an untested tree',

  run(ctx) {
    if (!shipsPipeline(ctx)) return [];
    const out = [];
    const path = stubPath(STUB_FILE);
    const text = ctx.read(path);

    if (!text.includes(`./.github/workflows/${ORCHESTRATOR_CALL}`)) {
      out.push(finding(rule, {
        file: path,
        what: `does not call the local ./.github/workflows/${ORCHESTRATOR_CALL} — the orchestrator owns only the triggers, the logic is the reusable workflow`,
        fix: `re-copy the orchestrator from the pack's stubs/workflows/${STUB_FILE}`,
      }));
    }
    // Release ON PUSH is the standard, not a per-repo choice: a site whose
    // deploy waits for a human to remember it drifts from its own main.
    if (!/^\s*push:/m.test(text)) {
      out.push(finding(rule, {
        file: path,
        what: 'has no push: trigger — the standard releases on push to main',
        fix: `re-copy the orchestrator from the pack's stubs/workflows/${STUB_FILE}`,
      }));
    }

    for (const wf of VENDORED_WORKFLOWS) {
      if (ctx.read(stubPath(wf)) === null) {
        out.push(finding(rule, {
          file: stubPath(wf),
          what: 'missing — the orchestrator calls this local reusable workflow',
          fix: `copy it from the pack's stubs/workflows/${wf}`,
        }));
      }
    }
    for (const action of VENDORED_ACTIONS) {
      const file = `.github/actions/${action}/action.yml`;
      if (ctx.read(file) === null) {
        out.push(finding(rule, {
          file,
          what: 'missing — the vendored workflows use this local composite action',
          fix: `copy it (and the files beside it) from the pack's stubs/actions/${action}/`,
        }));
      }
    }
    // build_vars is opt-in, and so is this: a repo that never declares one is
    // untouched by the exporter's arrival and stays on its older vendored copy
    // quite happily. Declaring one is the moment the older copy becomes WRONG —
    // it reads the key, ignores it, and builds with the variable unset — and
    // that failure is silent all the way to the live page, so it is caught here
    // instead. This is the shape to reuse when a stub gains a capability: gate
    // the conformance on the repo having asked for it.
    const declaresBuildVars = (() => {
      const cfg = ctx.read('.github/site.config');
      if (cfg === null) return false;
      return Boolean(parseConfig(cfg).values.get('build_vars')?.trim());
    })();
    if (declaresBuildVars) {
      const exporter = `.github/actions/${VENDORED_ACTIONS[0]}/export-build-vars.mjs`;
      if (ctx.read(exporter) === null) {
        out.push(finding(rule, {
          file: exporter,
          what: 'missing, but .github/site.config declares build_vars — the vendored action predates the exporter, so the declared variables reach the build as nothing at all',
          fix: `copy it from the pack's stubs/actions/${VENDORED_ACTIONS[0]}/ (re-copy the whole directory, the action.yml gained an output too)`,
        }));
      }
      for (const wf of ['static-site-deploy-pages.yml', CI_STUB_FILE]) {
        const text = ctx.read(stubPath(wf));
        if (text !== null && !text.includes('export-build-vars.mjs')) {
          out.push(finding(rule, {
            file: stubPath(wf),
            what: 'runs build_command without exporting the build_vars the config declares — the build sees none of them',
            fix: `re-copy it from the pack's stubs/workflows/${wf}`,
          }));
        }
      }
    }

    // The gate. A pipeline that releases on push with nothing checking the pull
    // request publishes whatever merged.
    if (ctx.read(stubPath(CI_STUB_FILE)) === null && !ctx.tracked.some((f) => /^\.github\/workflows\/.*ci.*\.ya?ml$/i.test(f))) {
      out.push(finding(rule, {
        file: stubPath(CI_STUB_FILE),
        what: 'missing — a repo that releases on push has no gate unless its pull requests run one',
        fix: `copy the pack's stubs/workflows/${CI_STUB_FILE} (conformance sweep + the repo's gate + the publish-set assembly dry run)`,
      }));
    }
    return out;
  },
};

export default rule;

